<script setup>
import { ref, computed, watch } from 'vue';
import { brewApi } from '../api';
import FermentationExecution from './FermentationExecution.vue';
import ProductionPlanDetail from './ProductionPlanDetail.vue';
const props = defineProps({ tankId: [String,Number] });
const emit = defineEmits(['close']);
const tank=ref(null), loading=ref(false), error=ref(''), tab=ref('overview'), historyPlan=ref(null);
let request=0;
const production=computed(()=>tank.value?.production);
const plan=computed(()=>production.value?.plan);
const mash=computed(()=>production.value?.tasks.find(t=>t.task_type==='mashing'));
const ferment=computed(()=>production.value?.tasks.find(t=>t.task_type==='fermentation'));
const completion=computed(()=>plan.value?.brewing_completion);
const usage=computed(()=>tank.value?.history_summary);
const locationChecks=computed(()=>tank.value?.location_checks||[]);
const fill=computed(()=>tank.value?.capacity_l>0?Math.max(0,Math.min(100,100*tank.value.current_volume_l/tank.value.capacity_l)):0);
const freeVolume=computed(()=>Math.max(0,Number(tank.value?.capacity_l||0)-Number(tank.value?.current_volume_l||0)));
const recentBatch=computed(()=>tank.value?.history?.[0]);
const shortDate=value=>value?new Date(/[zZ]|[+-]\d\d:\d\d$/.test(value)?value:`${value}Z`).toLocaleDateString('zh-CN'):'暂无记录';
const number=value=>Number(value||0).toLocaleString('zh-CN',{maximumFractionDigits:3});
const date=value=>value?new Date(/[zZ]|[+-]\d\d:\d\d$/.test(value)?value:`${value}Z`).toLocaleString('zh-CN',{hour12:false}):'—';
const packagingState=value=>({draft:'待开始',in_progress:'包装中',pending_release:'待放行',released:'已放行',cancelled:'已取消'})[value]||'未知状态';
const metricDefs=[['temperature','温度','℃'],['pressure','压力','bar'],['gravity','糖度','°P'],['attenuation','实际发酵度','%']];
async function load(){const id=props.tankId,key=++request;if(!id)return;loading.value=true;error.value='';try{const result=await brewApi.getTank(id);if(!result?.factory||!result?.stage)throw new Error('罐体详情返回不完整，请刷新重试。');if(key===request)tank.value=result;}catch(cause){if(key===request)error.value=cause.message||'罐体详情加载失败。';}finally{if(key===request)loading.value=false;}}
watch(()=>props.tankId,async()=>{tank.value=null;tab.value='overview';historyPlan.value=null;await load();},{immediate:true});
</script>
<template>
<div v-if="tankId" class="equipment-modal-mask tank-detail-mask" @click.self="emit('close')"><section class="equipment-modal tank-detail-modal" role="dialog" aria-modal="true" aria-label="罐体状态详情">
<header class="equipment-modal-header"><div><div class="modal-title">{{ tank?.name||'罐体详情' }}<span v-if="tank" class="tank-detail-status">{{ tank.stage_label }}</span></div><div v-if="tank" class="modal-subtitle">{{ tank.factory.name }} · {{ tank.tank_type==='bright'?'清酒罐':'发酵罐' }} · 容量 {{ number(tank.capacity_l) }} L</div></div><button class="equipment-close" aria-label="关闭罐体详情" @click="emit('close')">×</button></header>
<div class="equipment-modal-body tank-detail-body">
<div v-if="error" class="master-error" role="alert">{{ error }}</div><div v-if="loading&&!tank" class="empty">正在加载罐体与批次记录…</div>
<template v-if="tank">
<section class="tank-current" :class="{empty:!tank.current_volume_l}">
  <div class="tank-current-product"><span>{{ tank.current_volume_l>0?'当前酒液':plan?'当前生产安排':'当前状态' }}</span><h2>{{ tank.current_volume_l>0 ? tank.current_product||plan?.product.name||'在罐酒液' : plan?.product.name||(locationChecks.length?'位置待核对':'空罐') }}</h2><p v-if="tank.current_volume_l>0||plan">{{ tank.current_batch_no||plan?.batch?.name||plan?.name||'批次待核对' }}</p><p v-else>{{ locationChecks.length ? '有历史原液余额未确认去向' : '暂无酒液占用记录' }}</p></div>
  <div class="tank-volume"><span>{{ locationChecks.length ? '当前在罐记录' : '在罐酒液' }}</span><div><strong>{{ number(tank.current_volume_l) }}</strong><small> / {{ number(tank.capacity_l) }} L</small></div><div class="tank-fill" role="meter" aria-label="罐体使用容量" :aria-valuenow="tank.current_volume_l" aria-valuemin="0" :aria-valuemax="tank.capacity_l"><i :style="{width:fill+'%'}"></i></div><p>{{ locationChecks.length ? '实际余量待现场核对' : '剩余容量 '+number(freeVolume)+' L' }}</p></div>
</section>
<div v-if="tank.open_anomaly_count||['maintenance','abnormal','retained'].includes(tank.stage)" class="tank-attention" role="status"><span v-if="tank.open_anomaly_count">{{ tank.open_anomaly_count }} 项异常待处理</span><span v-if="tank.stage==='maintenance'">罐体维护中，暂不安排使用</span><span v-if="tank.stage==='abnormal'">罐体状态异常，请核对生产记录</span><span v-if="tank.stage==='retained'">计划已关闭，酒液仍占用罐体</span></div>
<section v-if="locationChecks.length" class="tank-location-checks" aria-label="原液待核对"><strong>原液待核对</strong><div v-for="row in locationChecks" :key="row.plan_id"><div><span>{{ row.product }} · {{ number(row.volume_l) }} L</span><small>{{ row.batch_name }} · 历史原液余额，实际位置尚未确认</small></div><button class="tank-text-button" @click="historyPlan=row.plan_id">查看批次 →</button></div></section>
<section class="tank-usage" aria-label="历史生产统计"><div><span>累计实际产酒</span><strong>{{ usage?number(usage.actual_volume_l):'—' }}<small> L</small></strong></div><div><span>完成生产批次</span><strong>{{ usage?number(usage.completed_batches):'—' }}<small> 批</small></strong></div><div><span>最近完成</span><strong class="tank-last-date">{{ shortDate(usage?.last_completed_at) }}</strong></div></section>
<nav class="tank-detail-tabs" aria-label="罐体详情分类"><button :class="{active:tab==='overview'}" @click="tab='overview'">状态概况</button><button v-if="production||tank.session" :class="{active:tab==='execution'}" @click="tab='execution'">工艺与执行记录</button><button :class="{active:tab==='history'}" @click="tab='history'">生产历史 <small v-if="usage">{{ usage.completed_batches }}</small></button></nav>
<div v-if="tank.production_error" class="master-error">{{ tank.production_error }}</div>
<template v-if="tab==='overview'">
<section v-if="tank.current_volume_l>0||production" class="tank-detail-section"><h3>最新实测数据</h3><div class="tank-detail-metrics"><article v-for="[key,label,unit] in metricDefs" :key="key"><span>{{ label }}</span><strong>{{ tank.latest_metrics[key]?number(tank.latest_metrics[key].value)+' '+unit:'未记录' }}</strong><small v-if="tank.latest_metrics[key]">{{ date(tank.latest_metrics[key].at) }} · {{ tank.latest_metrics[key].by }}</small></article></div><p class="rw-hint">仅显示已经实际测量的记录；未来日期的预填数据不作为当前读数。</p></section>
<section v-if="plan" class="tank-detail-section"><h3>关联生产安排</h3><div class="tank-detail-summary"><div><span>糖化负责人</span><strong>{{ plan.mash_owner?.name||'待分配' }}</strong></div><div><span>发酵负责人</span><strong>{{ plan.fermentation_owner?.name||'待分配' }}</strong></div><div><span>计划产量</span><strong>{{ number(plan.planned_volume_l) }} L</strong></div><div><span>酿造系统</span><strong>{{ plan.equipment.name }}</strong></div></div></section>
<section v-if="completion?.confirmed_at" class="tank-detail-section tank-completion"><h3>酿酒结束确认</h3><p><strong>{{ completion.confirmed_by }}</strong> · {{ date(completion.confirmed_at) }}</p><div class="tank-detail-summary"><div><span>实际产酒</span><strong>{{ number(completion.actual_volume_l) }} L</strong></div><div><span>损耗</span><strong>{{ number(completion.loss_volume_l) }} L</strong></div><div><span>酒液去向</span><strong>{{ completion.destination }}</strong></div><div><span>结束时酒液状态</span><strong>{{ completion.disposition==='in_tank'?'仍在罐内':'已出酒并排空' }}</strong></div></div><p v-if="completion.note" class="rw-hint">{{ completion.note }}</p></section>
<section v-if="['raw_ready','ready','packaged'].includes(tank.stage)||tank.packaging_orders.length" class="tank-detail-section"><h3>包装进度</h3><div v-for="order in tank.packaging_orders" :key="order.id" class="tank-packaging-row"><div><strong>{{ order.name }} · {{ packagingState(order.state) }}</strong><small>{{ order.packaging }} · 计划 {{ number(order.planned_volume_l) }} L</small><small v-if="order.released_at">放行于 {{ date(order.released_at) }} · 产出 {{ number(order.output_volume_l) }} L / {{ number(order.output_qty) }} 件</small></div></div><p v-if="tank.stage === 'packaged' && !tank.packaging_orders.length" class="rw-hint">已包装，按用户确认登记。</p><p v-else-if="!tank.packaging_orders.length" class="rw-hint">当前批次尚未创建包装单，暂无包装与放行记录。</p></section>
<section v-if="recentBatch" class="tank-detail-section tank-recent"><header><h3>最近生产</h3><button class="tank-text-button" @click="tab='history'">查看历史 →</button></header><div><div><strong>{{ recentBatch.product }}</strong><small>{{ recentBatch.name }} · {{ shortDate(recentBatch.completed_at) }}</small></div><strong>{{ number(recentBatch.volume_l) }} <small>L</small></strong><button class="tank-text-button" @click="historyPlan=recentBatch.plan_id">查看批次 →</button></div></section>
<p v-else-if="!production && !tank.current_volume_l" class="tank-history-empty">暂无已完成的生产记录</p>
</template>
<template v-if="tab==='execution'">
<section v-if="mash" class="tank-detail-section"><h3>糖化工艺节点 · {{ mash.execution_checkpoints.filter(n=>n.state==='done').length }}/{{ mash.execution_checkpoints.length }} 项</h3><ol class="tank-node-list"><li v-for="node in mash.execution_checkpoints" :key="node.code"><span :class="{done:node.state==='done'}">{{ node.state==='done'?'✓':'○' }}</span><div><strong>{{ node.title }}</strong><small v-if="node.target">目标：{{ node.target }}</small><small v-if="node.value!==undefined&&node.value!==''">实测 / 操作结果：{{ node.value }} {{ node.unit||'' }}</small><small v-if="node.completed_at">{{ date(node.completed_at) }} · {{ node.completed_by }}</small><small v-else>未完成</small></div></li></ol></section>
<FermentationExecution v-if="ferment" :task="ferment" :can-operate="false" />
<section v-if="tank.session&&!ferment" class="tank-detail-section"><h3>发酵会话</h3><p>{{ tank.session.name }} · 开始于 {{ date(tank.session.started_at) }}</p><p class="rw-hint">当前会话未关联按天任务，以上实测数据来自已审核读数。</p></section>
</template>
<template v-if="tab==='history'">
<section v-if="production" class="tank-detail-section"><h3>当前批次流程记录</h3><ol class="tank-node-list"><li v-for="(event,i) in production.timeline" :key="i"><span>·</span><div><strong>{{ event.title }}</strong><small>{{ date(event.at) }} · {{ event.by||'系统' }}</small><small v-if="event.value!==undefined">{{ event.value }}</small></div></li></ol></section>
<section class="tank-detail-section"><header class="tank-history-heading"><h3>历史生产批次</h3><span>最近 {{ tank.history.length }} 批 · 按实际产量统计</span></header><div v-for="batch in tank.history" :key="batch.id" class="tank-packaging-row"><div><strong>{{ batch.name }} · {{ batch.product }}</strong><small>{{ number(batch.volume_l) }} L · {{ date(batch.completed_at) }}</small></div><button class="btn btn-sm btn-outline" @click="historyPlan=batch.plan_id">查看批次</button></div><p v-if="!tank.history.length" class="rw-hint">暂无已完成的历史关联批次。</p></section>
</template>
</template>
</div><footer class="equipment-modal-footer"><button class="btn btn-secondary" @click="emit('close')">关闭</button><button class="btn btn-outline" :disabled="loading" @click="load">刷新详情</button><button v-if="plan" class="btn btn-primary" @click="historyPlan=plan.id">查看完整批次流程</button></footer>
</section></div>
<ProductionPlanDetail :plan-id="historyPlan" @close="historyPlan=null" />
</template>
<style scoped>
.tank-detail-modal{width:min(900px,calc(100vw - 32px));max-height:90dvh;display:flex;flex-direction:column}.tank-detail-body{display:block;min-height:0;overflow:auto;padding:22px 26px}.tank-detail-modal>.equipment-modal-header{padding:20px 26px;background:none}.tank-detail-modal .modal-title{display:flex;align-items:center;gap:12px;font-size:21px}.tank-detail-status{font-size:11px;font-weight:400;color:var(--text-secondary);background:#ffffff08;padding:3px 8px;border-radius:5px}.tank-detail-modal .modal-subtitle{font-size:11px;margin-top:6px}.tank-current{display:grid;grid-template-columns:minmax(0,1fr) 240px;gap:24px;align-items:center;padding:4px 0 22px}.tank-current-product>span,.tank-volume>span{font-size:11px;color:var(--text-muted)}.tank-current-product h2{font-size:22px;font-weight:600;margin:8px 0 5px}.tank-current-product p,.tank-volume p{font-size:11px;color:var(--text-muted);margin:5px 0 0}.tank-current.empty .tank-current-product h2{font-size:20px;color:var(--text-secondary)}.tank-volume strong{font-size:28px;font-weight:600;font-variant-numeric:tabular-nums}.tank-volume small{font-size:12px;color:var(--text-muted)}.tank-fill{height:5px;border-radius:3px;background:#ffffff0c;overflow:hidden;margin-top:10px}.tank-fill i{display:block;height:100%;background:var(--accent-gold);border-radius:3px}.tank-attention{display:flex;gap:14px;flex-wrap:wrap;padding:10px 12px;margin-bottom:14px;background:#d4a8530d;color:#dabc83;border-radius:5px;font-size:12px}.tank-location-checks{margin-bottom:18px;padding:12px 14px;background:#d4a8530b;border-left:2px solid #d4a85380;border-radius:4px}.tank-location-checks>strong{font-size:12px;font-weight:500;color:#dabc83}.tank-location-checks>div{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-top:10px}.tank-location-checks span{font-size:12px}.tank-location-checks small{display:block;font-size:10px;color:var(--text-muted);margin-top:3px}.tank-usage{display:grid;grid-template-columns:1fr 1fr 1.1fr;padding:16px 0;border-top:1px solid var(--border-default);border-bottom:1px solid var(--border-default)}.tank-usage>div{padding:0 18px;border-left:1px solid var(--border-subtle)}.tank-usage>div:first-child{padding-left:0;border:0}.tank-usage span{display:block;font-size:11px;color:var(--text-muted)}.tank-usage strong{display:block;font-size:24px;font-weight:500;margin-top:6px;font-variant-numeric:tabular-nums}.tank-usage strong small{font-size:11px;font-weight:400;color:var(--text-muted)}.tank-usage .tank-last-date{font-size:15px;margin-top:13px}.tank-detail-tabs{display:flex;gap:22px;border-bottom:1px solid var(--border-default);margin:14px 0 18px}.tank-detail-tabs button{padding:10px 0;background:none;border:0;border-bottom:2px solid transparent;color:var(--text-muted);cursor:pointer;font-size:12px}.tank-detail-tabs button.active{color:var(--accent-gold);border-color:var(--accent-gold)}.tank-detail-tabs small{font-size:10px;margin-left:4px}.tank-detail-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:12px 0}.tank-detail-summary span,.tank-detail-metrics article>span{display:block;font-size:11px;color:var(--text-muted);margin-bottom:6px}.tank-detail-summary strong{display:block;font-size:12px;font-weight:500;overflow-wrap:anywhere}.tank-detail-section{margin-top:22px}.tank-detail-section h3{font-size:13px;font-weight:500;margin-bottom:12px}.tank-detail-section p{font-size:12px;line-height:1.7}.tank-detail-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.tank-detail-metrics article{padding:0 12px 0 0}.tank-detail-metrics strong{font-size:18px;display:block;font-weight:500}.tank-detail-metrics small,.tank-node-list small,.tank-packaging-row small{display:block;font-size:10px;color:var(--text-muted);margin-top:6px}.tank-detail-section .rw-hint{font-size:10px;color:var(--text-muted);margin-top:12px}.tank-node-list{list-style:none;padding:0}.tank-node-list li{display:flex;gap:14px;padding:12px 0;border-bottom:1px solid var(--border-subtle)}.tank-node-list li>span{color:var(--text-muted)}.tank-node-list li>span.done{color:var(--success)}.tank-node-list strong{font-size:12px;font-weight:500}.tank-packaging-row{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid var(--border-subtle);font-size:12px}.tank-completion{border-top:1px solid var(--border-subtle);padding-top:18px}.tank-detail-modal>.equipment-modal-footer{flex-shrink:0;padding:14px 26px}.tank-detail-modal>.equipment-modal-footer .btn{height:34px;padding:0 12px;font-size:12px}.tank-recent>header,.tank-history-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.tank-recent>header h3,.tank-history-heading h3{margin:0}.tank-recent>div{display:flex;gap:20px;align-items:center;padding:14px 0 0}.tank-recent>div>div{flex:1}.tank-recent>div>div>strong{font-size:13px;font-weight:500}.tank-recent small{display:block;font-size:11px;color:var(--text-muted);margin-top:5px}.tank-recent>div>strong{font-size:18px;font-weight:500}.tank-recent>div>strong small{display:inline}.tank-text-button{border:0;background:none;color:var(--accent-gold);font-size:11px;white-space:nowrap;cursor:pointer}.tank-history-heading>span{font-size:10px;color:var(--text-muted)}.tank-history-empty{color:var(--text-muted);font-size:12px;margin:24px 0 10px;text-align:center}.tank-detail-modal button:focus-visible{outline:2px solid var(--accent-gold);outline-offset:2px}
@media(max-width:650px){.tank-current{grid-template-columns:1fr;gap:16px}.tank-detail-body{padding:18px}.tank-usage>div{padding:0 10px}.tank-usage strong{font-size:21px}.tank-usage .tank-last-date{font-size:12px}.tank-detail-summary,.tank-detail-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.tank-detail-tabs{gap:14px}.tank-packaging-row,.tank-recent>div{flex-wrap:wrap}.tank-history-heading{flex-wrap:wrap}}
</style>
